ALTER TABLE app.zero_t ALTER COLUMN id SET STATISTICS 0;
ALTER TABLE app.default_t ALTER COLUMN id SET STATISTICS DEFAULT;
ALTER TABLE app.limit_t ALTER COLUMN id SET STATISTICS 10000;
ALTER TABLE app.options_t ALTER COLUMN id SET(n_distinct=-0.5);
